import { useEffect, useState, type FormEvent } from 'react';
import { Activity, Building2, CreditCard, FileKey, Fingerprint, KeyRound, LayoutDashboard, LogOut, Menu, ShieldCheck, Users, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
type Mode = 'password' | 'totp';
type Admin = { userName?: string | null; email?: string | null; totpEnabled?: boolean; passkeyCount?: number; mustChangePassword?: boolean };
type PasskeyRequestOptionsJson = Omit<PublicKeyCredentialRequestOptions, 'challenge' | 'allowCredentials'> & { challenge: string; allowCredentials?: Array<Omit<PublicKeyCredentialDescriptor, 'id'> & { id: string }> };
type PasskeyCreationOptionsJson = Omit<PublicKeyCredentialCreationOptions, 'challenge' | 'user' | 'excludeCredentials'> & { challenge: string; user: Omit<PublicKeyCredentialUserEntity, 'id'> & { id: string }; excludeCredentials?: Array<Omit<PublicKeyCredentialDescriptor, 'id'> & { id: string }> };
type TotpSetup = { sharedKey: string; authenticatorUri: string };
type ApiError = { error?: string; message?: string };
async function apiError(response: Response) { try { const body = await response.json() as ApiError; return body.error ?? body.message ?? 'درخواست انجام نشد.'; } catch { return 'ارتباط با سامانه برقرار نشد.'; } }

function decodeBase64Url(value: string): ArrayBuffer {
 const normalized=value.replace(/-/g,'+').replace(/_/g,'/');
 const binary=atob(normalized+'='.repeat((4-normalized.length%4)%4));
 const bytes=new Uint8Array(binary.length);
 for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
 return bytes.buffer;
}
function encodeBase64Url(value: ArrayBuffer): string {
 const bytes=new Uint8Array(value);let binary='';
 for(let i=0;i<bytes.length;i++)binary+=String.fromCharCode(bytes[i]);
 return btoa(binary).replace(/\\+/g,'-').replace(/\\//g,'_').replace(/=+$/,'');
}
function decodeCredentialDescriptors<T extends {id:string;type:PublicKeyCredentialType;transports?:AuthenticatorTransport[]}>(items:T[]|undefined):PublicKeyCredentialDescriptor[]|undefined {
 return items?.map(item=>({id:decodeBase64Url(item.id),type:item.type,transports:item.transports}));
}
function serializeAssertion(credential:PublicKeyCredential):string {
 const response=credential.response as AuthenticatorAssertionResponse;
 return JSON.stringify({id:credential.id,rawId:encodeBase64Url(credential.rawId),type:credential.type,authenticatorAttachment:credential.authenticatorAttachment,response:{clientDataJSON:encodeBase64Url(response.clientDataJSON),authenticatorData:encodeBase64Url(response.authenticatorData),signature:encodeBase64Url(response.signature),userHandle:response.userHandle?encodeBase64Url(response.userHandle):null},clientExtensionResults:credential.getClientExtensionResults()});
}
function serializeAttestation(credential:PublicKeyCredential):string {
 const response=credential.response as AuthenticatorAttestationResponse;
 return JSON.stringify({id:credential.id,rawId:encodeBase64Url(credential.rawId),type:credential.type,authenticatorAttachment:credential.authenticatorAttachment,response:{clientDataJSON:encodeBase64Url(response.clientDataJSON),attestationObject:encodeBase64Url(response.attestationObject),transports:response.getTransports?.()??[]},clientExtensionResults:credential.getClientExtensionResults()});
}
function requireWebAuthn():void {
 if(!window.isSecureContext||!navigator.credentials||typeof PublicKeyCredential==='undefined')throw new Error('ورود با کلید عبور فقط در مرورگر سازگار و اتصال امن HTTPS در دسترس است.');
}
export default function App() {
 const [admin,setAdmin]=useState<Admin|null>(null),[checking,setChecking]=useState(true),[mode,setMode]=useState<Mode>('password'),[userName,setUserName]=useState(''),[password,setPassword]=useState(''),[code,setCode]=useState(''),[showPassword,setShowPassword]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[navOpen,setNavOpen]=useState(false),[totpSetup,setTotpSetup]=useState<TotpSetup|null>(null),[totpSetupCode,setTotpSetupCode]=useState('');
 useEffect(()=>{let active=true;fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'}).then(async r=>{if(r.ok&&active)setAdmin(await r.json() as Admin)}).catch(()=>{}).finally(()=>{if(active)setChecking(false)});return()=>{active=false}},[]);
 async function token(){const r=await fetch('/api/auth/antiforgery',{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw new Error('دریافت توکن امنیتی ناموفق بود.');const data=await r.json() as {requestToken?:string};if(!data.requestToken)throw new Error('توکن امنیتی در پاسخ سرور وجود ندارد.');return data.requestToken}
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;setBusy(true);setError('');setNotice('');try{const csrf=await token();const endpoint=mode==='password'?'/api/auth/password':'/api/auth/totp/verify';const payload=mode==='password'?{userName:userName.trim(),password}:{code:code.trim()};const r=await fetch(endpoint,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify(payload)});if(!r.ok)throw new Error(await apiError(r));if(mode==='password'){const result=await r.json() as {requiresSecondFactor?:boolean;method?:string};if(!result.requiresSecondFactor||result.method!=='totp')throw new Error('پاسخ احراز هویت با قرارداد مورد انتظار سازگار نیست.');setMode('totp');setPassword('');setNotice('رمز عبور پذیرفته شد؛ کد یک‌بارمصرف را وارد کنید.');return}const me=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'});if(!me.ok)throw new Error('نشست معتبر پس از تأیید ایجاد نشد.');setAdmin(await me.json() as Admin);setCode('')}catch(err){setError(err instanceof Error?err.message:'ورود ناموفق بود.')}finally{setBusy(false)}}
 async function passkeyLogin(){if(busy)return;setBusy(true);setError('');setNotice('');try{requireWebAuthn();const csrf=await token();const optionResponse=await fetch('/api/auth/passkey/options',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({userName:userName.trim()||null})});if(!optionResponse.ok)throw new Error(await apiError(optionResponse));const json=await optionResponse.json() as PasskeyRequestOptionsJson;const options:PublicKeyCredentialRequestOptions={...json,challenge:decodeBase64Url(json.challenge),allowCredentials:decodeCredentialDescriptors(json.allowCredentials as unknown as Array<{id:string;type:PublicKeyCredentialType;transports?:AuthenticatorTransport[]}>) };const credential=await navigator.credentials.get({publicKey:options});if(!credential||!(credential instanceof PublicKeyCredential))throw new Error('تأیید کلید عبور انجام نشد.');const verify=await fetch('/api/auth/passkey/sign-in',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({credentialJson:serializeAssertion(credential)})});if(!verify.ok)throw new Error(await apiError(verify));const me=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'});if(!me.ok)throw new Error('نشست معتبر پس از تأیید کلید عبور ایجاد نشد.');setAdmin(await me.json() as Admin);setPassword('');setCode('')}catch(err){setError(err instanceof DOMException&&err.name==='NotAllowedError'?'درخواست کلید عبور لغو شد یا زمان آن پایان یافت.':err instanceof Error?err.message:'ورود با کلید عبور ناموفق بود.')}finally{setBusy(false)}}
 async function registerPasskey(){if(busy)return;setBusy(true);setError('');setNotice('');try{requireWebAuthn();const csrf=await token();const optionResponse=await fetch('/api/auth/passkey/creation-options',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'X-CSRF-TOKEN':csrf}});if(!optionResponse.ok)throw new Error(await apiError(optionResponse));const json=await optionResponse.json() as PasskeyCreationOptionsJson;const options:PublicKeyCredentialCreationOptions={...json,challenge:decodeBase64Url(json.challenge),user:{...json.user,id:decodeBase64Url(json.user.id)},excludeCredentials:decodeCredentialDescriptors(json.excludeCredentials as unknown as Array<{id:string;type:PublicKeyCredentialType;transports?:AuthenticatorTransport[]}>) };const credential=await navigator.credentials.create({publicKey:options});if(!credential||!(credential instanceof PublicKeyCredential))throw new Error('ثبت کلید عبور تکمیل نشد.');const register=await fetch('/api/auth/passkey/register',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({credentialJson:serializeAttestation(credential),displayName:'کلید عبور مرورگر'})});if(!register.ok)throw new Error(await apiError(register));const me=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'});if(!me.ok)throw new Error('نشست پس از ثبت کلید عبور معتبر نماند.');setAdmin(await me.json() as Admin);setNotice('کلید عبور با موفقیت ثبت شد.');}catch(err){setError(err instanceof DOMException&&err.name==='NotAllowedError'?'ثبت کلید عبور لغو شد یا زمان آن پایان یافت.':err instanceof Error?err.message:'ثبت کلید عبور ناموفق بود.')}finally{setBusy(false)}}
 async function startTotpSetup(){if(busy)return;setBusy(true);setError('');setNotice('');try{const csrf=await token();const r=await fetch('/api/auth/totp/setup',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'X-CSRF-TOKEN':csrf}});if(!r.ok)throw new Error(await apiError(r));const data=await r.json() as TotpSetup;if(!data.sharedKey||!data.authenticatorUri)throw new Error('اطلاعات راه‌اندازی احراز هویت ناقص است.');setTotpSetup(data);setTotpSetupCode('');}catch(err){setError(err instanceof Error?err.message:'راه‌اندازی TOTP ناموفق بود.')}finally{setBusy(false)}}
 async function confirmTotpSetup(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;setBusy(true);setError('');setNotice('');try{const csrf=await token();const r=await fetch('/api/auth/totp/confirm',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({code:totpSetupCode.trim()})});if(!r.ok)throw new Error(await apiError(r));const me=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'});if(!me.ok)throw new Error('نشست معتبر پس از فعال‌سازی TOTP تأیید نشد.');setAdmin(await me.json() as Admin);setTotpSetup(null);setTotpSetupCode('');setNotice('احراز هویت TOTP فعال شد. کلید مشترک را از این صفحه خارج نکنید.');}catch(err){setError(err instanceof Error?err.message:'تأیید TOTP ناموفق بود.')}finally{setBusy(false)}}
 async function logout(){setBusy(true);setError('');try{const csrf=await token();const r=await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'X-CSRF-TOKEN':csrf}});if(!r.ok)throw new Error(await apiError(r));setAdmin(null);setMode('password');setPassword('');setCode('');setTotpSetup(null);setNotice('با موفقیت خارج شدید.')}catch(err){setError(err instanceof Error?err.message:'خروج انجام نشد.')}finally{setBusy(false)}}
 if(checking)return <main className="boot-screen" aria-live="polite"><div className="brand-mark">F</div><p>در حال بررسی نشست امن…</p></main>;
 if(!admin)return <main className="login-layout"><section className="brand-panel"><div className="brand-lockup"><div className="brand-mark">F</div><div><b>فرانو</b><small>FARANOU · CONTROL PLANE</small></div></div><div className="brand-copy"><span className="eyebrow"><ShieldCheck size={16}/> مرکز مدیریت فروشنده</span><h1>کنترل دقیق‌تر،<br/><em>تصمیم مطمئن‌تر.</em></h1><p>مدیریت متمرکز مشتریان تجاری، نصب‌ها و مجوزهای نرم‌افزار؛ در یک محیط امن و مستقل.</p><div className="brand-point"><Building2/><span><b>مدیریت یکپارچه</b><small>آماده برای رشد شبکه مشتریان</small></span></div><div className="brand-point"><KeyRound/><span><b>امنیت چندلایه</b><small>نشست محدود و احراز هویت دومرحله‌ای</small></span></div><div className="brand-point"><Activity/><span><b>ردیابی‌پذیری</b><small>پایه‌گذاری برای عملیات قابل ممیزی</small></span></div></div><footer>FARANOU <span>سامانه مرکزی فروشنده</span></footer></section><section className="login-panel"><div className="login-wrap"><div className="mobile-brand"><div className="brand-mark">F</div><b>فرانو <small>پنل مرکزی فروشنده</small></b></div><span className="eyebrow">دسترسی مدیریتی</span><h2>{mode==='password'?'به پنل مرکزی وارد شوید':'تأیید هویت دومرحله‌ای'}</h2><p className="intro">{mode==='password'?'اطلاعات حساب مدیر فروشنده را وارد کنید.':'کد فعلی برنامه احراز هویت را برای '+userName+' وارد کنید.'}</p><Card className="login-card"><CardHeader><CardTitle>{mode==='password'?'ورود امن':'کد یک‌بارمصرف'}</CardTitle><CardDescription>{mode==='password'?'ورود فقط با حساب مدیر فعال و دارای MFA امکان‌پذیر است.':'کد شش‌رقمی برنامه احراز هویت را وارد کنید.'}</CardDescription></CardHeader><CardContent><form className="auth-form" onSubmit={submit}>{mode==='password'?<><label htmlFor="username">نام کاربری یا ایمیل</label><input id="username" autoComplete="username" required maxLength={256} value={userName} onChange={e=>setUserName(e.target.value)} placeholder="نام کاربری مدیر" disabled={busy}/><label htmlFor="password">رمز عبور</label><div className="password-field"><input id="password" type={showPassword?'text':'password'} autoComplete="current-password" required maxLength={1024} value={password} onChange={e=>setPassword(e.target.value)} placeholder="رمز عبور حساب" disabled={busy}/><button type="button" className="password-toggle" onClick={()=>setShowPassword(v=>!v)} aria-label={showPassword?'پنهان کردن رمز عبور':'نمایش رمز عبور'}>{showPassword?'پنهان':'نمایش'}</button></div></>:<><label htmlFor="totp">کد احراز هویت</label><input id="totp" autoComplete="one-time-code" inputMode="numeric" pattern="[0-9]{6}" minLength={6} maxLength={6} required value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,'').slice(0,6))} placeholder="کد شش‌رقمی" disabled={busy} dir="ltr"/><button className="text-action" type="button" onClick={()=>{setMode('password');setCode('');setError('');setNotice('')}}>بازگشت به ورود</button></>}{error&&<div className="message error" role="alert">{error}</div>}{notice&&<div className="message notice" role="status">{notice}</div>}<Button className="submit-button" type="submit" size="lg" disabled={busy}>{busy?'در حال بررسی…':mode==='password'?'ادامه و تأیید هویت':'تأیید و ورود'} <span>←</span></Button>{mode==='password'&&<Button type="button" variant="outline" className="passkey-button" onClick={passkeyLogin} disabled={busy}><Fingerprint size={18}/>{busy?'در حال بررسی…':'ورود با کلید عبور (Passkey)'}</Button>}</form></CardContent></Card><div className="security-note"><ShieldCheck/><span><b>اتصال امن و هم‌مبدأ</b><small>کوکی محافظت‌شده، نشست کوتاه‌مدت و محافظت ضدجعل درخواست.</small></span></div><p className="legal">این سامانه مخصوص مدیران مجاز فروشنده است.</p></div></section></main>;
 const items=[['نمای کلی',LayoutDashboard],['مشتریان تجاری',Users],['نصب‌ها',Building2],['مجوزها و لایسنس‌ها',FileKey],['اشتراک‌ها و قراردادها',CreditCard]] as const;
 return <div className="workspace" dir="rtl"><aside className={'sidebar '+(navOpen?'sidebar-open':'')}><div className="sidebar-brand"><div className="brand-mark small">F</div><div><b>فرانو</b><small>مرکز کنترل فروشنده</small></div><button className="mobile-close" aria-label="بستن منو" onClick={()=>setNavOpen(false)}><X/></button></div><p className="nav-caption">فضای مدیریتی</p><nav aria-label="منوی اصلی">{items.map(([label,Icon],i)=><button key={label} className={'nav-item '+(i===0?'active':'')} onClick={()=>setNotice('بخش «'+label+'» پس از تکمیل API و مجوزهای سرور فعال می‌شود.')}><Icon size={18}/>{label}{i===0&&<span className="nav-dot"/>}</button>)}</nav><div className="sidebar-bottom">FARANOU CONTROL PLANE<small>نسخه اولیه رابط</small></div></aside>{navOpen&&<button className="scrim" aria-label="بستن منو" onClick={()=>setNavOpen(false)}/>}<section className="main-area"><header className="topbar"><div className="top-title"><button className="mobile-menu" aria-label="باز کردن منو" onClick={()=>setNavOpen(true)}><Menu/></button><div><small>پنل فروشنده</small><b>نمای کلی</b></div></div><div className="top-actions"><span className="secure"><i/> نشست امن</span><div className="avatar">{(admin.userName??'م').slice(0,1)}</div><div className="admin-name"><b>{admin.userName??'مدیر فروشنده'}</b><small>مدیر سامانه مرکزی</small></div><Button variant="outline" size="sm" onClick={logout} disabled={busy}><LogOut size={15}/> خروج</Button></div></header><main className="dashboard"><div className="page-heading"><div><span className="eyebrow">خوش آمدید</span><h1>مرکز کنترل فرانو</h1><p>وضعیت کلی سامانه و مسیرهای مدیریتی در یک نگاه.</p></div><span className="preview-badge">نسخه اولیه پنل</span></div>{error&&<div className="message error" role="alert">{error}</div>}{notice&&<div className="message notice" role="status">{notice}</div>}<div className="readiness"><ShieldCheck/><div><b>زیرساخت مدیریتی در حال تکمیل است</b><p>ورود و نشست از API واقعی استفاده می‌کنند. بخش‌های تجاری پس از تکمیل مجوزهای سرور و مدل داده فعال خواهند شد.</p></div><span>در حال توسعه</span></div><div className="metrics"><Card className="metric"><CardContent><span>مشتریان تجاری</span><b>—</b><small>پس از تکمیل API مدیریت مشتریان</small></CardContent></Card><Card className="metric"><CardContent><span>نصب‌های ثبت‌شده</span><b>—</b><small>پس از تکمیل مدل نصب</small></CardContent></Card><Card className="metric"><CardContent><span>لایسنس‌های فعال</span><b>—</b><small>پس از پیاده‌سازی چرخه لایسنس</small></CardContent></Card><Card className="metric"><CardContent><span>وضعیت نشست</span><b className="green">فعال</b><small>نشست تأییدشده سمت سرور</small></CardContent></Card></div><div className="panels"><Card><CardHeader><CardTitle>گام‌های بعدی توسعه</CardTitle><CardDescription>ماژول‌ها تا تکمیل قراردادهای سرور غیرفعال هستند.</CardDescription></CardHeader><CardContent><div className="roadmap-row"><b>۰۱</b><span><strong>تکمیل RBAC و bootstrap مدیران</strong><small>مجوزها و ایجاد امن نخستین مدیر</small></span><em>در حال انجام</em></div><div className="roadmap-row"><b>۰۲</b><span><strong>مدیریت مشتریان و نصب‌ها</strong><small>مدل دامنه، API و رویدادهای ممیزی</small></span><em>بعدی</em></div><div className="roadmap-row"><b>۰۳</b><span><strong>صدور و اعتبارسنجی لایسنس</strong><small>جریان امضاشده با کلید خارج از برنامه مشتری</small></span><em>بعدی</em></div></CardContent></Card><Card><CardHeader><CardTitle>وضعیت امنیت حساب</CardTitle><CardDescription>اطلاعات نشست فعلی</CardDescription></CardHeader><CardContent><div className="account-row"><span>نام کاربری</span><b>{admin.userName??'—'}</b></div><div className="account-row"><span>احراز هویت TOTP</span><b>{admin.totpEnabled?'فعال':'نیازمند بررسی'}</b></div><div className="account-row"><span>Passkey ثبت‌شده</span><b>{admin.passkeyCount??'—'}</b></div><p className="security-foot"><ShieldCheck size={16}/> مجوز عملیات حساس باید در سرور بررسی شود.</p><div className="security-actions"><Button variant="outline" onClick={registerPasskey} disabled={busy}><Fingerprint size={16}/> ثبت کلید عبور</Button>{!admin.totpEnabled&&<Button variant="outline" onClick={startTotpSetup} disabled={busy}><KeyRound size={16}/> راه‌اندازی TOTP</Button>}</div>{totpSetup&&<div className="totp-setup"><b>راه‌اندازی برنامهٔ احراز هویت</b><p>این کلید محرمانه است؛ آن را فقط در برنامهٔ احراز هویت خود وارد کنید. این صفحه آن را در حافظهٔ مرورگر نگه می‌دارد و در Web Storage ذخیره نمی‌کند.</p><code dir="ltr">{totpSetup.sharedKey}</code><details><summary>نمایش URI برنامهٔ احراز هویت</summary><code dir="ltr">{totpSetup.authenticatorUri}</code></details><form className="auth-form" onSubmit={confirmTotpSetup}><label htmlFor="totp-setup-code">کد شش‌رقمی برای تأیید</label><input id="totp-setup-code" autoComplete="one-time-code" inputMode="numeric" pattern="[0-9]{6}" minLength={6} maxLength={6} required value={totpSetupCode} onChange={e=>setTotpSetupCode(e.target.value.replace(/\\D/g,'').slice(0,6))} disabled={busy} dir="ltr"/><Button type="submit" disabled={busy}>تأیید و فعال‌سازی TOTP</Button><Button type="button" variant="ghost" onClick={()=>{setTotpSetup(null);setTotpSetupCode('')}} disabled={busy}>لغو</Button></form></div>}</CardContent></Card></div><footer className="dashboard-footer">فرانو · داده‌های آماری تا زمان اتصال API نمایش داده نمی‌شوند.</footer></main></section></div>
}
